// The snippets are generated by scripts/build.mjs from the official template.
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import { check } from '../out/core.mjs';

const snippets = JSON.parse(await readFile(new URL('../dist/snippets.json', import.meta.url), 'utf8'));
const template = await readFile(new URL('../vendor/lernatelier-checker-js/templates/Lernperiode-NR.md', import.meta.url), 'utf8');

/** Expands a snippet body like VS Code does when every placeholder keeps its default. */
function expand(body, date = { CURRENT_DATE: '13', CURRENT_MONTH: '11', CURRENT_YEAR: '2026' }) {
  let text = body.join('\n').replace(/\$\{(CURRENT_\w+)\}/g, (_, v) => date[v]);
  for (let i = 0; i < 5; i++) text = text.replace(/\$\{(\d+):((?:[^{}\\]|\\.)*)\}/g, '$2');
  text = text.replace(/\$0/g, '');
  return text.replace(/\\([$}\\])/g, '$1');
}

test('every snippet has a prefix, description and body', () => {
  assert.deepEqual(Object.keys(snippets), ['Lernperiode (Vorlage)', 'Tagesplanung', 'Tagesreflexion', 'Tagesreflexion mit Leitfragen', 'Arbeitspaket']);
  for (const s of Object.values(snippets)) {
    assert.ok(s.prefix.length && s.description && s.body.length);
  }
});

test('the Lernperiode snippet expands to exactly the official template', () => {
  assert.equal(expand(snippets['Lernperiode (Vorlage)'].body).trimEnd(), template.trimEnd());
});

test('filled-in Lernperiode snippet is recognised: number, name, period', () => {
  const body = snippets['Lernperiode (Vorlage)'].body.join('\n')
    .replace('${1:NR}', '6').replace('${2:Exemplibus Exemplio}', 'Max Beispiel')
    .replace('${3:tt.mm.jjjj}', '06.11.2026').replace('${4:tt.mm.jjjj}', '18.12.2026')
    .replace('${5:tt.mm.jjjj}', '13.11.2026');
  const doc = check(expand(body.split('\n')), {}, '2026-11-13').result.document;
  assert.equal(doc.number, 6);
  assert.equal(doc.name, 'Max Beispiel');
  assert.deepEqual(doc.period, { start: '2026-11-06', end: '2026-12-18' });
  assert.equal(doc.days[0].date, '2026-11-13');
});

test('the day snippet uses today and its placeholders count as unfilled', () => {
  const day = expand(snippets['Tagesplanung'].body);
  assert.match(day, /^### Planung 13\.11\.2026$/m);
  const doc = check(`# Lern-Periode 1\n## Tagesplanungen\n${day}`, {}, '2026-11-13').result.document;
  assert.equal(doc.days[0].date, '2026-11-13');
  assert.equal(doc.days[0].tasks.length, 3);
  assert.ok(doc.days[0].tasks.every(t => !t.filled), 'placeholders must not count as work packages');
  assert.equal(doc.days[0].reflection.wordCount, 0);
});

test('task and reflection snippets', () => {
  assert.equal(expand(snippets['Arbeitspaket'].body), '- [ ] ...Ihr Text...');
  assert.equal(expand(snippets['Tagesreflexion'].body).trim(), '#### Tagesreflexion\n\n...Ihr Text...');
});
